bool_t xdr_string(XDR *xdrs, char **objp)
{
    u_int i;
    u_int len;
    u_int elen;
    char *sp;
    bool_t stat = TRUE;

    if (!xdrs || !objp)
        return FALSE;

    if (xdrs->x_op == XDR_FREE) {
        if (*objp != NULL) {
            free(*objp);
            *objp = NULL;
        }
        return TRUE;
    }

    if (xdrs->x_op == XDR_ENCODE) {
        if (*objp == NULL) {
            sp = "";
        } else {
            sp = *objp;
        }
        len = strlen(sp) + 1;
        if (!xdr_u_int(xdrs, &len))
            return FALSE;
        if (len > 0) {
            if (!xdr_opaque(xdrs, sp, len))
                return FALSE;
        }
        return TRUE;
    }

    if (xdrs->x_op == XDR_DECODE) {
        if (!xdr_u_int(xdrs, &len))
            return FALSE;
        elen = len;
        if (elen == 0) {
            *objp = "";
            return TRUE;
        }
        sp = *objp;
        if (sp == NULL) {
            sp = (char *)malloc(elen);
            if (sp == NULL)
                return FALSE;
            *objp = sp;
        }
        if (!xdr_opaque(xdrs, sp, elen))
            return FALSE;
        sp[elen - 1] = '\0';  /* ensure null-termination */
        return TRUE;
    }

    return FALSE;
}

bool_t xdr_string(XDR *xdrs, char **objp)
{
    long int size;
    char *sp;
    int32_t *buf;

    if (xdrs->x_op == XDR_ENCODE) {
        if (*objp == NULL) {
            size = 0;
        } else {
            size = strlen(*objp);
        }

        if (!xdr_u_long(xdrs, &size)) {
            return FALSE;
        }

        if (size == 0) {
            return TRUE;
        }

        return xdr_opaque(xdrs, *objp, size);
    }

    if (xdrs->x_op == XDR_DECODE) {
        if (!xdr_u_long(xdrs, &size)) {
            return FALSE;
        }

        if (size == 0) {
            *objp = NULL;
            return TRUE;
        }

        sp = *objp;
        if (sp == NULL) {
            sp = (char *)mem_alloc(size + 1);
            if (sp == NULL) {
                return FALSE;
            }
            *objp = sp;
        }

        if (!xdr_opaque(xdrs, sp, size)) {
            return FALSE;
        }

        sp[size] = '\0';
        return TRUE;
    }

    if (xdrs->x_op == XDR_FREE) {
        if (*objp != NULL) {
            mem_free(*objp, strlen(*objp) + 1);
            *objp = NULL;
        }
        return TRUE;
    }

    return FALSE;
}

