            }
        }
        return TRUE;
    } else if (xdrs->x_op == XDR_DECODE) {
        if (!XDR_GETLONG(xdrs, &len)) {
            return FALSE;
        }
        if (len == 0) {
            *objp = NULL;
            return TRUE;
        }
        sp = *objp;
        if (sp == NULL) {
            sp = (char *)malloc(len + 1);
            if (sp == NULL) {
                return FALSE;
            }
            *objp = sp;
        } else {
            sp = (char *)realloc(sp, len + 1);
            if (sp == NULL) {
                return FALSE;
            }
            *objp = sp;
        }
        if (!xdr_opaque(xdrs, sp, len)) {
            return FALSE;
        }
        sp[len] = '\0';
        return TRUE;
